#include <stdio.h>



int main(void) {
    int r, c, value, maximum = 0, row = 1, column = 1;
    scanf("%d%d", &r, &c);
    for (int i = 1; i <= r; i++) for (int j = 1; j <= c; j++) {
        scanf("%d", &value);
        if ((i == 1 && j == 1) || value > maximum) { maximum = value; row = i; column = j; }
    }
    printf("%d %d %d\n", maximum, row, column);
    return 0;
}
